const newItems = $('Check Scraper Errors').all(); // Clean items
// Safely get reference data directly from node execution
// Note: Reference nodes ran sequentially, so data MUST be there
const existingNews = $('Get Existing News').all(); 
const cachedNews = $('Get Cache').all();

const existingUrls = new Set();
if (existingNews && existingNews.length) {
  existingNews.forEach(i => { if(i.json.url) existingUrls.add(i.json.url); });
}

const cachedMap = new Map();
if (cachedNews && cachedNews.length) {
  cachedNews.forEach(i => {
    if(i.json.url) cachedMap.set(i.json.url, i.json);
  });
}

const toProcess = [];

for (const item of newItems) {
  const url = item.json.link || item.json.url;

  // Deduplicate
  if (existingUrls.has(url)) continue;

  // Cache Check
  if (cachedMap.has(url)) {
      const cached = cachedMap.get(url);
      item.json = {
          ...item.json,
          ...JSON.parse(cached.result_json || '{}'),
          is_cached: true
      };
  } else {
      item.json.is_cached = false;
      const raw_text = item.json.content || item.json.description || item.json.summary || "";
      // AGENT PROMPT: FINANCIAL ANALYST (STRICT JSON)
      item.json.prompt_para_api = `### Role:\nYou are a Senior Financial Analyst at a top Wall Street firm. Your job is to analyze market news and provide actionable investment insights.\n\n### Instructions:\n1. Analyze the news content below.\n2. Determine the sentiment and potential market impact.\n3. Provide investment advice based on the news.\n4. Create a prompt for an AI image generator to visualize this news.\n5. OUTPUT MUST BE STRICT VALID JSON ONLY. NO MARKDOWN. NO BACKTICKS.\n\n### Content:\n${raw_text}\n\n### Output Schema (JSON Only):\n{\n  "title": "Spanish Title (Concise)",\n  "summary": "Concise summary of the news content in Spanish",\n  "sentiment": "BULLISH | BEARISH | NEUTRAL",\n  "risk_level": "LOW | MEDIUM | HIGH",\n  "market_impact": "Spanish explanation of impact",\n  "action": "BUY | SELL | HOLD",\n  "investment_advice": { "rating": "...", "reasoning": "..." },\n  "image_prompt": "English detailed prompt for image generation, vector art style"\n}`;

      // ATTACH METADATA FOR PRESERVATION
      item.json.metadata_para_api = {
          url: url,
          source_content: raw_text
      };
  }
  toProcess.push(item);
}

return toProcess;

// AGGREGATOR NODE: Combine all items in the batch into a SINGLE request payload
// This prevents the HTTP Request node from executing multiple times in parallel

const noticias = items.map(item => ({
    text: item.json.prompt_para_api,
    metadata: item.json.metadata_para_api
}));

return [{
    json: {
        payload: {
            noticias: noticias,
            callback_url: "http://34.9.244.104:5678/webhook/webhook-callback"
        }
    }
}];

// Prepare content for Cache Saving
for (const item of items) {
  item.json.result_json = JSON.stringify(item.json);
}
return items;

for (const item of items) {
  const llmResult = typeof item.json.result === 'string' ? JSON.parse(item.json.result) : item.json.result;
  const subjectPrompt = item.json.image_prompt || (llmResult ? llmResult.image_prompt : '') || 'Financial graph';

  // ENFORCED STYLE
  const style = "flat vector art, modern corporate memphis style, financial technology aesthetic, minimalist, clean lines, vibrant blue and white colors, high quality";
  const fullPrompt = `${subjectPrompt}, ${style}`;

  const encodedPrompt = encodeURIComponent(fullPrompt);
  const seed = Math.floor(Math.random() * 10000);
  const imageUrl = `https://image.pollinations.ai/prompt/${encodedPrompt}?width=800&height=600&seed=${seed}`;

  item.json = {
    ...item.json,
    ...llmResult,
    generated_image_url: imageUrl,
    temp_id: 'news_' + Math.floor(Math.random()*100000)
  };
}
return items;

for (const item of items) {
   const bucket = 'alphaseeker-assets';
   let publicUrl = null;

   if (item.json.name && !item.json.error) {
       const filename = item.json.name;
       publicUrl = `https://storage.googleapis.com/${bucket}/${filename}`;
   }

   // EXTREME DATA DISCOVERY (Handle Doubly Nested n8n/Gemini Responses)
   let data = item.json;

   // 1. Try to parse 'result_json' if it exists (Common in n8n Loop nodes)
   if (item.json.result_json && typeof item.json.result_json === 'string') {
       try {
           const parsed = JSON.parse(item.json.result_json);
           if (parsed.body && parsed.body['body.results']) {
               // Found deep data
               data = parsed.body['body.results'];
           } else if (parsed.body && parsed.body.results) {
               data = parsed.body.results;
           } else {
               data = parsed;
           }
       } catch (e) {
           console.log('Failed to parse result_json');
       }
   }

   // 2. Direct body checks (Priority: 'body.results' sibling, then nested)
   // CRITICAL FIX: Do NOT put sibling check in 'else' of body check
   if (item.json['body.results']) {
      data = item.json['body.results'];
   } else if (item.json.body) {
      if (item.json.body.results) data = item.json.body.results;
      else if (item.json.body['body.results']) data = item.json.body['body.results'];
   }

   // 3. Fallback for mixed up keys (sometimes they sit on root)
   if (!data.title && item.json.noticia_principal) data = item.json;

   // MAP SPANISH KEYS TO ENGLISH SCHEMA
   item.json = {
       ...item.json,
       title: data.noticia_principal || data.titulo_noticia || data.title || 'Market News',
       content_summary: data.summary || data.resumen || data.content_summary || '',
       // NEW: Map Full Content from preserved metadata or fallback
       content: data.source_content || data.metadata?.source_content || data.content || '',
       published_date: data.fecha_publicacion || new Date().toISOString(),
       url: data.url || item.json.url || '',
       source: 'n8n',
       investment_advice: data.recomendacion_inversion || data.investment_advice || {},
       market_impact: data.impacto_mercado || data.market_impact || '',
       risk_level: data.nivel_riesgo || data.risk_level || '',
       sentiment: data.sentimiento || data.sentiment || '',
       analysis: data.analisis_financiero || data.analysis || '',
       action: data.accion_recomendada || data.action || '',
       image_url: publicUrl
   };
}
return items;
